    #view-support.support-shell .support-search-clear.visible{display:grid}
    #view-support.support-shell .support-filter-tabs{display:flex;align-items:center;gap:3px;overflow:auto;margin-bottom:12px;border-bottom:1px solid var(--line)}
    #view-support.support-shell .support-filter-tab{flex:0 0 auto;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);padding:8px 9px;font:inherit;font-size:11px;cursor:pointer;white-space:nowrap}
